using Microsoft.EntityFrameworkCore;
using TaskTrack.Repo.Models;
using AsyncTask = System.Threading.Tasks.Task;

namespace TaskTrack.Repo.Data;

public static class AuthSchemaInitializer
{
    public static AsyncTask EnsureCreated(TaskManagementContext db, CancellationToken ct) => db.Database.ExecuteSqlRawAsync("""
        CREATE TABLE IF NOT EXISTS "SystemAccount" (
            "AccountID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
            "FullName" varchar(150) NOT NULL,
            "Email" varchar(254) NOT NULL UNIQUE,
            "PasswordHash" varchar(255) NOT NULL,
            "Role" smallint NOT NULL DEFAULT 0,
            "CreatedDate" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
        );
        ALTER TABLE "Task" ADD COLUMN IF NOT EXISTS "CreatedByID" integer NULL;
        ALTER TABLE "Task" ADD COLUMN IF NOT EXISTS "UpdatedByID" integer NULL;
        DO $$ BEGIN
            IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_Task_CreatedBy') THEN
                ALTER TABLE "Task" ADD CONSTRAINT "FK_Task_CreatedBy" FOREIGN KEY ("CreatedByID") REFERENCES "SystemAccount"("AccountID") ON DELETE RESTRICT;
            END IF;
            IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_Task_UpdatedBy') THEN
                ALTER TABLE "Task" ADD CONSTRAINT "FK_Task_UpdatedBy" FOREIGN KEY ("UpdatedByID") REFERENCES "SystemAccount"("AccountID") ON DELETE RESTRICT;
            END IF;
        END $$;
        """, ct);

    public static async AsyncTask EnsureAdmin(TaskManagementContext db, string? email, string? password, string? fullName, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(email) || string.IsNullOrWhiteSpace(password)) return;
        var normalized = email.Trim().ToLowerInvariant();
        var account = await db.SystemAccounts.FirstOrDefaultAsync(a => a.Email == normalized, ct);
        if (account is null)
        {
            db.SystemAccounts.Add(new SystemAccount
            {
                FullName = string.IsNullOrWhiteSpace(fullName) ? "TaskTrack Administrator" : fullName.Trim(),
                Email = normalized, PasswordHash = BCrypt.Net.BCrypt.HashPassword(password), Role = 1,
                CreatedDate = DateTime.SpecifyKind(DateTime.UtcNow, DateTimeKind.Unspecified)
            });
        }
        else if (account.Role != 1)
        {
            account.Role = 1;
        }
        else return;
        await db.SaveChangesAsync(ct);
    }
}
